#!/usr/bin/env node
// plank-join: join every @planks(...) annotation on a production seam to a current
// step-definition pattern, and redden where the join fails. Also reports unplanked seams
// and step-definition patterns bound by no plank.
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const IMPL_DIRS = ['js'];
const STEP_DIRS = ['features/step_definitions'];

function walk(dir, out) {
  const abs = path.join(ROOT, dir);
  if (!fs.existsSync(abs)) return out;
  for (const entry of fs.readdirSync(abs, { withFileTypes: true })) {
    const rel = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(rel, out);
    else if (entry.name.endsWith('.js')) out.push(rel);
  }
  return out;
}

function readPatterns() {
  const patterns = new Set();
  for (const dir of STEP_DIRS) {
    for (const file of walk(dir, [])) {
      const src = fs.readFileSync(path.join(ROOT, file), 'utf8');
      const re = /\b(?:Given|When|Then)\s*\(\s*(['"])((?:\\.|(?!\1)[^\\])*)\1/g;
      let m;
      while ((m = re.exec(src)) !== null) patterns.add(m[2]);
    }
  }
  return patterns;
}

// A seam is a top-level declaration: function, class, class method, or const arrow.
const DECL = /^\s*(?:module\.exports\s*=\s*)?(?:async\s+)?(?:function\s+([A-Za-z0-9_$]+)|class\s+([A-Za-z0-9_$]+)|(?:const|let|var)\s+([A-Za-z0-9_$]+)\s*=\s*(?:async\s*)?(?:function\b|\()|([A-Za-z0-9_$]+)\s*\([^)]*\)\s*\{)/;

function readSeams() {
  const seams = [];
  for (const dir of IMPL_DIRS) {
    for (const file of walk(dir, [])) {
      const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
      for (let i = 0; i < lines.length; i++) {
        const decl = DECL.exec(lines[i]);
        if (!decl) continue;
        const name = decl[1] || decl[2] || decl[3] || decl[4];
        if (!name || name === 'if' || name === 'for' || name === 'while' || name === 'switch')
          continue;
        // Collect the docblock immediately above the declaration.
        let j = i - 1;
        const block = [];
        while (j >= 0 && lines[j].trim() === '') j--;
        if (j >= 0 && lines[j].trim().endsWith('*/')) {
          while (j >= 0) {
            block.unshift(lines[j]);
            if (lines[j].trim().startsWith('/**')) break;
            j--;
          }
        }
        const doc = block.join('\n');
        const planks = [];
        const provisional = [];
        const pre = /@planks\(\s*"((?:\\.|[^"\\])*)"\s*\)/g;
        const prov = /@planks-provisional\(\s*"((?:\\.|[^"\\])*)"\s*\)/g;
        let m;
        while ((m = prov.exec(doc)) !== null) provisional.push(m[1]);
        const docNoProv = doc.replace(/@planks-provisional/g, '@__prov__');
        while ((m = pre.exec(docNoProv)) !== null) planks.push(m[1]);
        seams.push({ file, line: i + 1, name, planks, provisional });
      }
    }
  }
  return seams;
}

function bareTokens() {
  const hits = [];
  for (const dir of IMPL_DIRS) {
    for (const file of walk(dir, [])) {
      const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (!lines[i].includes('@planks')) continue;
        const t = lines[i].trim();
        if (!t.startsWith('*') && !t.startsWith('/**')) hits.push(`${file}:${i + 1}`);
      }
    }
  }
  return hits;
}

const patterns = readPatterns();
const seams = readSeams();
const stale = [];
const unplanked = [];
const used = new Set();

for (const seam of seams) {
  if (seam.planks.length === 0 && seam.provisional.length === 0) {
    unplanked.push(`${seam.file}:${seam.line} ${seam.name}`);
    continue;
  }
  for (const p of seam.planks) {
    if (patterns.has(p)) used.add(p);
    else stale.push(`${seam.file}:${seam.line} ${seam.name} -> "${p}"`);
  }
}

const orphans = [...patterns].filter((p) => !used.has(p));
const bare = bareTokens();

console.log(`patterns: ${patterns.size}`);
console.log(`seams: ${seams.length}`);
console.log(`planked seams: ${seams.length - unplanked.length}`);
for (const p of [...patterns].sort()) console.log(`  pattern: "${p}"${used.has(p) ? '' : '  [no plank]'}`);
if (unplanked.length) {
  console.log('UNPLANKED SEAMS:');
  for (const u of unplanked) console.log(`  ${u}`);
}
if (stale.length) {
  console.log('STALE OR MALFORMED PLANKS:');
  for (const s of stale) console.log(`  ${s}`);
}
if (bare.length) {
  console.log('BARE @planks TOKENS OUTSIDE A DOCBLOCK:');
  for (const b of bare) console.log(`  ${b}`);
}
if (orphans.length) {
  console.log('STEP PATTERNS WITH NO PLANK:');
  for (const o of orphans) console.log(`  "${o}"`);
}

const failed = stale.length > 0 || unplanked.length > 0 || bare.length > 0;
console.log(failed ? 'plank-join: FAIL' : 'plank-join: OK');
process.exit(failed ? 1 : 0);

