'use strict';

const assert = require('node:assert/strict');
const { Given, When, Then } = require('@cucumber/cucumber');

const ENTER_KEY = 13;
const ESCAPE_KEY = 27;

// ---------------------------------------------------------------------------
// Query helpers. The app re-renders its list, so every helper re-queries the
// live document rather than holding an element across steps.
// ---------------------------------------------------------------------------

function items(world) {
  return [...world.document.querySelectorAll('.todo-list li')];
}

function titles(world) {
  return items(world).map((li) => li.querySelector('label').textContent.trim());
}

function itemTitled(world, title) {
  const found = items(world).find(
    (li) =>
      li.querySelector('label').textContent.trim() === title ||
      (li.querySelector('.edit') && li.querySelector('.edit').value === title)
  );
  assert.ok(found, `no todo titled "${title}" is on the list; the list shows ${JSON.stringify(titles(world))}`);
  return found;
}

function isHidden(world, element) {
  assert.ok(element, 'the element is absent from the page');
  const style = world.window.getComputedStyle(element);
  return element.hasAttribute('hidden') || style.display === 'none' || style.visibility === 'hidden';
}

function section(world, name) {
  return world.document.querySelector(`.${name}`) || world.document.querySelector(`#${name}`);
}

function newTodoField(world) {
  const field = world.document.querySelector('.new-todo');
  assert.ok(field, 'the page carries no .new-todo field');
  return field;
}

function toggleAll(world) {
  const box = world.document.querySelector('.toggle-all');
  assert.ok(box, 'the page carries no .toggle-all checkbox');
  return box;
}

function fire(world, element, type, init = {}) {
  element.dispatchEvent(new world.window.Event(type, { bubbles: true, ...init }));
}

function key(world, element, keyName, keyCode) {
  for (const type of ['keydown', 'keyup']) {
    const event = new world.window.KeyboardEvent(type, {
      key: keyName,
      code: keyName,
      keyCode,
      which: keyCode,
      bubbles: true,
      cancelable: true,
    });
    element.dispatchEvent(event);
  }
}

function typeInto(world, field, text) {
  field.value = text;
  fire(world, field, 'input');
}

function addTodo(world, title) {
  const field = newTodoField(world);
  typeInto(world, field, title);
  key(world, field, 'Enter', ENTER_KEY);
}

function editFieldOf(world, title) {
  const field = itemTitled(world, title).querySelector('.edit');
  assert.ok(field, `the todo titled "${title}" carries no .edit field`);
  return field;
}

function storedRecords(world) {
  const raw = world.localStorage.getItem('todos-vanillajs');
  assert.ok(raw, 'the "todos-vanillajs" storage key holds nothing');
  return JSON.parse(raw);
}

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded with no stored todos', function () {
  assert.equal(this.localStorage.getItem('todos-vanillajs'), null);
  assert.deepEqual(titles(this), []);
});

Given('the app is loaded with the todos {string}', function (list) {
  for (const title of list.split(',').map((t) => t.trim())) addTodo(this, title);
  assert.deepEqual(titles(this), list.split(',').map((t) => t.trim()));
});

Given('the person starts editing the todo titled {string}', function (title) {
  fire(this, itemTitled(this, title).querySelector('label'), 'dblclick');
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When('the person adds a todo titled {string}', function (title) {
  addTodo(this, title);
});

When('the person removes the todo titled {string}', function (title) {
  const button = itemTitled(this, title).querySelector('.destroy');
  assert.ok(button, `the todo titled "${title}" carries no .destroy button`);
  button.click();
});

When('the person toggles the todo titled {string}', function (title) {
  itemTitled(this, title).querySelector('.toggle').click();
});

When('the person checks the mark all as complete checkbox', function () {
  const box = toggleAll(this);
  if (!box.checked) box.click();
  assert.equal(box.checked, true, 'the mark all as complete checkbox refused the check');
});

When('the person unchecks the mark all as complete checkbox', function () {
  const box = toggleAll(this);
  if (box.checked) box.click();
});

When('the person clicks clear completed', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page carries no .clear-completed button');
  button.click();
});

When('the person double-clicks the label of the todo titled {string}', function (title) {
  fire(this, itemTitled(this, title).querySelector('label'), 'dblclick');
});

When('the person types {string} and presses Enter', function (text) {
  const field = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(field, 'no todo is in editing mode');
  typeInto(this, field, text);
  key(this, field, 'Enter', ENTER_KEY);
});

When('the person types {string} and blurs the edit field', function (text) {
  const field = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(field, 'no todo is in editing mode');
  typeInto(this, field, text);
  fire(this, field, 'blur');
});

When('the person types {string} and presses Escape', function (text) {
  const field = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(field, 'no todo is in editing mode');
  typeInto(this, field, text);
  key(this, field, 'Escape', ESCAPE_KEY);
});

When('the person types {string} and presses Escape and blurs the edit field', function (text) {
  const field = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(field, 'no todo is in editing mode');
  typeInto(this, field, text);
  key(this, field, 'Escape', ESCAPE_KEY);
  fire(this, field, 'blur');
});

When('the person types {string} and presses Enter and reloads the page', async function (text) {
  const field = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(field, 'no todo is in editing mode');
  typeInto(this, field, text);
  key(this, field, 'Enter', ENTER_KEY);
  await this.reloadApp();
});

When('the person navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the person clicks the filter link reading {string}', function (label) {
  const link = [...this.document.querySelectorAll('.filters a')].find(
    (a) => a.textContent.trim() === label
  );
  assert.ok(link, `the filter list carries no link reading "${label}"`);
  link.click();
});

When('the person reloads the page', async function () {
  await this.reloadApp();
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('the {string} section is hidden', function (name) {
  assert.equal(isHidden(this, section(this, name)), true, `the "${name}" section is on screen`);
});

Then('the {string} section is visible', function (name) {
  assert.equal(isHidden(this, section(this, name)), false, `the "${name}" section is off screen`);
});

Then('the todo list shows the titles {string}', function (list) {
  assert.deepEqual(titles(this), list.split(',').map((t) => t.trim()));
});

Then('the todo list is empty', function () {
  assert.deepEqual(titles(this), []);
});

Then('the new todo field carries the {string} attribute', function (name) {
  assert.equal(newTodoField(this).hasAttribute(name), true);
});

Then('the new todo field is empty', function () {
  assert.equal(newTodoField(this).value, '');
});

Then('the todo titled {string} is marked completed', function (title) {
  assert.equal(itemTitled(this, title).classList.contains('completed'), true);
});

Then('the todo titled {string} is not marked completed', function (title) {
  assert.equal(itemTitled(this, title).classList.contains('completed'), false);
});

Then('the checkbox of the todo titled {string} is checked', function (title) {
  assert.equal(itemTitled(this, title).querySelector('.toggle').checked, true);
});

Then('the todo titled {string} carries a destroy button', function (title) {
  assert.ok(itemTitled(this, title).querySelector('button.destroy'));
});

Then('the todo titled {string} is in editing mode', function (title) {
  assert.equal(itemTitled(this, title).classList.contains('editing'), true);
});

Then('the todo titled {string} is not in editing mode', function (title) {
  assert.equal(itemTitled(this, title).classList.contains('editing'), false);
});

Then('the edit field of the todo titled {string} holds {string}', function (title, value) {
  assert.equal(editFieldOf(this, title).value, value);
});

Then('the edit field of the todo titled {string} holds the focus', function (title) {
  assert.equal(this.document.activeElement, editFieldOf(this, title));
});

Then('the mark all as complete checkbox is checked', function () {
  assert.equal(toggleAll(this).checked, true);
});

Then('the mark all as complete checkbox is not checked', function () {
  assert.equal(toggleAll(this).checked, false);
});

Then('the counter reads {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.ok(counter, 'the page carries no .todo-count element');
  assert.equal(counter.textContent.replace(/\s+/g, ' ').trim(), text);
});

Then("the counter's strong tag reads {string}", function (text) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'the counter wraps its number in no <strong> tag');
  assert.equal(strong.textContent.trim(), text);
});

Then('the clear completed button is hidden', function () {
  const button = this.document.querySelector('.clear-completed');
  if (!button) return;
  assert.equal(isHidden(this, button), true, 'the clear completed button is on screen');
});

Then('the clear completed button is visible', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page carries no .clear-completed button');
  assert.equal(isHidden(this, button), false, 'the clear completed button is off screen');
});

Then('the selected filter link reads {string}', function (label) {
  const selected = [...this.document.querySelectorAll('.filters a.selected')];
  assert.equal(selected.length, 1, `${selected.length} filter links carry the selected class`);
  assert.equal(selected[0].textContent.trim(), label);
});

Then('the {string} storage key holds one record titled {string}', function (storageKey, title) {
  const raw = this.localStorage.getItem(storageKey);
  assert.ok(raw, `the "${storageKey}" storage key holds nothing`);
  const records = JSON.parse(raw);
  assert.equal(records.length, 1);
  assert.equal(records[0].title, title);
});

Then('each stored record carries the keys {string}', function (list) {
  const expected = list.split(',').map((k) => k.trim());
  const records = storedRecords(this);
  assert.ok(records.length > 0, 'no record is stored');
  for (const record of records)
    for (const k of expected)
      assert.ok(k in record, `a stored record lacks the "${k}" key: ${JSON.stringify(record)}`);
});

