(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var todos = [];
  var editingId = null;
  var filter = 'all';
  var els = {};

  /**
   * @planks("the person reloads the page")
   */
  function readStore() {
    var raw = window.localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  }

  /**
   * @planks("the {string} storage key holds one record titled {string}")
   */
  function writeStore() {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  /**
   * @planks("each stored record carries the keys {string}")
   */
  function createId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
  }

  /**
   * @planks("the counter reads {string}")
   */
  function activeCount() {
    return todos.filter(function (todo) {
      return !todo.completed;
    }).length;
  }

  /**
   * @planks("the clear completed button is hidden")
   */
  function completedCount() {
    return todos.length - activeCount();
  }

  /**
   * @planks("the todo list shows the titles {string}")
   */
  function visibleTodos() {
    if (filter === 'active') {
      return todos.filter(function (todo) {
        return !todo.completed;
      });
    }
    if (filter === 'completed') {
      return todos.filter(function (todo) {
        return todo.completed;
      });
    }
    return todos;
  }

  /**
   * @planks("the todo list shows the titles {string}")
   * @planks("the todo titled {string} is in editing mode")
   * @planks("the todo titled {string} carries a destroy button")
   */
  function renderList() {
    els.list.innerHTML = '';
    visibleTodos().forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      if (todo.id === editingId) li.classList.add('editing');

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = todo.completed;
      toggle.addEventListener('click', function () {
        toggleTodo(todo.id);
      });

      var label = document.createElement('label');
      label.textContent = todo.title;
      label.addEventListener('dblclick', function () {
        startEditing(todo.id);
      });

      var destroy = document.createElement('button');
      destroy.className = 'destroy';
      destroy.addEventListener('click', function () {
        destroyTodo(todo.id);
      });

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = todo.title;
      edit.addEventListener('keydown', function (event) {
        var code = event.keyCode || event.which;
        if (code === ENTER_KEY) commitEdit(todo.id, edit.value);
        if (code === ESCAPE_KEY) cancelEdit();
      });
      edit.addEventListener('blur', function () {
        commitEdit(todo.id, edit.value);
      });

      li.appendChild(view);
      li.appendChild(edit);
      els.list.appendChild(li);
    });
  }

  /**
   * @planks("the counter reads {string}")
   * @planks("the counter's strong tag reads {string}")
   */
  function renderCounter() {
    var remaining = activeCount();
    els.count.innerHTML = '';
    var strong = document.createElement('strong');
    strong.textContent = String(remaining);
    els.count.appendChild(strong);
    els.count.appendChild(document.createTextNode(remaining === 1 ? ' item left' : ' items left'));
  }

  /**
   * @planks("the {string} section is hidden")
   * @planks("the clear completed button is hidden")
   * @planks("the mark all as complete checkbox is checked")
   */
  function renderChrome() {
    els.main.hidden = todos.length === 0;
    els.footer.hidden = todos.length === 0;
    els.clear.hidden = completedCount() === 0;
    els.toggleAll.checked = todos.length > 0 && activeCount() === 0;
  }

  /**
   * @planks("the selected filter link reads {string}")
   */
  function renderFilters() {
    var wanted = filter === 'all' ? '#/' : '#/' + filter;
    els.filters.forEach(function (link) {
      link.classList.toggle('selected', link.getAttribute('href') === wanted);
    });
  }

  /**
   * @planks("the todo list shows the titles {string}")
   */
  function render() {
    renderList();
    renderCounter();
    renderChrome();
    renderFilters();
    focusEditField();
  }

  /**
   * @planks("the edit field of the todo titled {string} holds the focus")
   */
  function focusEditField() {
    var field = els.list.querySelector('li.editing .edit');
    if (field) field.focus();
  }

  /**
   * @planks("the person adds a todo titled {string}")
   */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({ id: createId(), title: trimmed, completed: false });
    writeStore();
    render();
  }

  /**
   * @planks("the person removes the todo titled {string}")
   */
  function destroyTodo(id) {
    todos = todos.filter(function (todo) {
      return todo.id !== id;
    });
    writeStore();
    render();
  }

  /**
   * @planks("the person toggles the todo titled {string}")
   */
  function toggleTodo(id) {
    todos.forEach(function (todo) {
      if (todo.id === id) todo.completed = !todo.completed;
    });
    writeStore();
    render();
  }

  /**
   * @planks("the person checks the mark all as complete checkbox")
   * @planks("the person unchecks the mark all as complete checkbox")
   */
  function setAllCompleted(completed) {
    todos.forEach(function (todo) {
      todo.completed = completed;
    });
    writeStore();
    render();
  }

  /**
   * @planks("the person clicks clear completed")
   */
  function clearCompleted() {
    todos = todos.filter(function (todo) {
      return !todo.completed;
    });
    writeStore();
    render();
  }

  /**
   * @planks("the person double-clicks the label of the todo titled {string}")
   */
  function startEditing(id) {
    editingId = id;
    render();
  }

  /**
   * @planks("the person types {string} and presses Enter")
   * @planks("the person types {string} and blurs the edit field")
   */
  function commitEdit(id, value) {
    if (editingId !== id) return;
    editingId = null;
    var trimmed = value.trim();
    if (trimmed === '') {
      destroyTodo(id);
      return;
    }
    todos.forEach(function (todo) {
      if (todo.id === id) todo.title = trimmed;
    });
    writeStore();
    render();
  }

  /**
   * @planks("the person types {string} and presses Escape")
   */
  function cancelEdit() {
    editingId = null;
    render();
  }

  /**
   * @planks("the person navigates to {string}")
   * @planks("the person clicks the filter link reading {string}")
   */
  function readFilterFromHash() {
    var hash = window.location.hash.replace('#!', '#');
    if (hash === '#/active') filter = 'active';
    else if (hash === '#/completed') filter = 'completed';
    else filter = 'all';
  }

  /**
   * @planks("the person navigates to {string}")
   */
  function onHashChange() {
    readFilterFromHash();
    render();
  }

  /**
   * @planks("the person reloads the page")
   */
  function init() {
    els.newTodo = document.querySelector('.new-todo');
    els.list = document.querySelector('.todo-list');
    els.count = document.querySelector('.todo-count');
    els.main = document.querySelector('.main');
    els.footer = document.querySelector('.footer');
    els.clear = document.querySelector('.clear-completed');
    els.toggleAll = document.querySelector('.toggle-all');
    els.filters = Array.prototype.slice.call(document.querySelectorAll('.filters a'));

    todos = readStore();
    readFilterFromHash();

    els.newTodo.addEventListener('keydown', function (event) {
      var code = event.keyCode || event.which;
      if (code !== ENTER_KEY) return;
      var title = els.newTodo.value;
      if (title.trim() === '') return;
      els.newTodo.value = '';
      addTodo(title);
    });

    els.toggleAll.addEventListener('click', function () {
      setAllCompleted(els.toggleAll.checked);
    });

    els.clear.addEventListener('click', clearCompleted);
    window.addEventListener('hashchange', onHashChange);

    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

